132	  return vscode.Uri.from({
133	    scheme: LOAD_MORE_SCHEME,
134	    path: `/${node.list}`,
135	    query: JSON.stringify({ root: node.repo.root, list: node.list, limit: node.repo.limit(node.list) }),
