374	 * list redraws every row each time it grows, and most rows are never hovered.
375	 */
376	export function tooltip(node: Node): vscode.MarkdownString | undefined {
377	  switch (node.kind) {
378	    case 'commit': {
379	      const { commit, repo } = node;
380	      const sole = soleCheckpoint(commit);
381	      const row = sole ? repo.index?.row(sole) : undefined;
382	      const place = sole && sessionCount(row) === 1 ? sessionPlace(repo, row?.sessionId, sole) : [];
383	      return markdown([
384	        `**${plain(commit.subject)}**`,
385	        `Commit \`${commit.sha}\``,
386	        `${plain(commit.author)}, ${new Date(commit.authorTime * 1000).toLocaleString()}`,
387	        ...commit.checkpointIds.map((id) => `Checkpoint \`${id}\``),
388	        ...place,
389	        sole && repo.withoutData.has(sole) ? NO_DATA_TOOLTIP : undefined,
390	      ]);
391	    }
392	
393	    case 'checkpoint': {
394	      const { row, commit } = node;
395	      const within = node.sessionId ?? (sessionCount(row) === 1 ? row?.sessionId : undefined);
396	      return markdown([
397	        row?.message ? `**${plain(headline(row.message, 200))}**` : undefined,
398	        `Checkpoint \`${node.checkpointId}\``,
399	        commit ? `Commit \`${commit.sha}\`` : 'No commit on this branch carries this checkpoint.',
400	        row?.date ? new Date(row.date).toLocaleString() : undefined,
401	        ...sessionPlace(node.repo, within, node.checkpointId, node.position),
402	        node.repo.withoutData.has(node.checkpointId) ? NO_DATA_TOOLTIP : undefined,
403	      ]);
404	    }
405	
406	    case 'slot': {
407	      const { session } = node;
408	      return markdown([
409	        session.summary?.intent ? `**${plain(headline(session.summary.intent, 200))}**` : undefined,
410	        session.sessionId ? `Session \`${session.sessionId}\`` : undefined,
411	        session.createdAt ? new Date(session.createdAt).toLocaleString() : undefined,
412	        session.filesTouched.length > 0 ? `${session.filesTouched.length} files touched` : undefined,
413	        session.tokenUsage
414	          ? `${totalTokens(session.tokenUsage).toLocaleString()} tokens since the previous checkpoint`
415	          : undefined,
416	      ]);
417	    }
418	
419	    case 'session': {
420	      const { session } = node;
421	      const tokens = session.local?.tokens?.total;
422	      const named = session.name ?? session.lastPrompt ?? session.title;
423	      return markdown([
424	        named ? `**${plain(headline(named, 200))}**` : undefined,
425	        session.opening ? `Opening prompt: ${plain(headline(session.opening, 200))}` : undefined,
426	        // A session that is still going has moved on from the prompt that opened it.
427	        session.name && session.lastPrompt && session.lastPrompt !== session.name && session.lastPrompt !== session.opening
428	          ? `Latest prompt: ${plain(headline(session.lastPrompt, 200))}`
429	          : undefined,
430	        `Session \`${session.sessionId}\``,
431	        joinParts(session.agent, session.model, session.status) || undefined,
432	        session.branch ? `Branch ${plain(session.branch)}` : undefined,
433	        session.local?.turns !== undefined ? `${session.local.turns} turns` : undefined,
434	        tokens !== undefined ? `${tokens.toLocaleString()} tokens` : undefined,
435	        session.lastActive ? `Last active ${new Date(session.lastActive).toLocaleString()}` : undefined,
436	        checkpointCountText(session) ?? 'No checkpoints',
437	      ]);
438	    }
439	
440	    case 'trail': {
441	      const { trail, repo } = node;
442	      const hosted = repo.entireRepo;
443	      const state = joinParts(trail.phase ?? trail.status, trail.type, trail.priority === 'none' ? undefined : trail.priority);
444	      return markdown([
445	        `**${plain(headline(trail.title, 200))}**`,
446	        `Trail ${trail.number}${state ? `, ${plain(state)}` : ''}`,
447	        ...trail.changes.map((change) => {
448	          const branch = change.branch ? `\`${change.branch}\`` : 'no branch';
449	          const into = change.base ? ` into \`${change.base}\`` : '';
450	          const here = hosted && isCheckedOut(change, hosted, repo.branch) ? ', checked out here' : '';
451	          return `${plain(change.repository)} ${change.number}: ${branch}${into}${here}`;
452	        }),
453	        trail.assignees.length > 0 ? `Assigned to ${plain(trail.assignees.join(', '))}` : undefined,
454	        trail.lastActivityAt ? `Last activity ${new Date(trail.lastActivityAt).toLocaleString()}` : undefined,
455	      ]);
456	    }
457	
458	    default:
459	      return undefined;
460	  }
461	}
462	
463	/** The icon of a trail row, which follows the trail's phase. */
464	function trailIcon(trail: TrailSummary, checkedOut: boolean): vscode.ThemeIcon {
465	  if (trail.status === 'closed' || trail.phase === 'closed') return muted('git-pull-request-closed');
466	  const icon =
467	    trail.phase === 'complete' ? 'pass' : trail.phase === 'planning' ? 'git-pull-request-draft' : 'git-pull-request';
468	  return checkedOut ? new vscode.ThemeIcon(icon, new vscode.ThemeColor('charts.green')) : new vscode.ThemeIcon(icon);
469	}
470	
471	export function treeItem(node: Node): vscode.TreeItem {
472	  const item = buildItem(node);
473	  item.id = nodeId(node);
474	  return item;
475	}
476	
477	function buildItem(node: Node): vscode.TreeItem {
478	  switch (node.kind) {
479	    case 'repo': {
480	      const item = new vscode.TreeItem(node.repo.name, vscode.TreeItemCollapsibleState.Expanded);
481	      item.description = node.repo.branch ?? '';
482	      item.iconPath = new vscode.ThemeIcon('repo');
483	      item.tooltip = node.repo.root;
484	      item.contextValue = 'repo';
485	      return item;
486	    }
487	
488	    case 'commit': {
489	      const { commit, repo } = node;
490	      const sole = soleCheckpoint(commit);
491	      const row = sole ? repo.index?.row(sole) : undefined;
492	      const sessions = sessionCount(row);
493	      const noData = sole !== undefined && repo.withoutData.has(sole);
494	      // Rows under a commit exist to tell things apart: its checkpoints when
495	      // it carries several, or its sessions when its checkpoint holds several.
496	      // A checkpoint with one session has neither, and the commit row stands
497	      // for it. Otherwise one long session would appear as a row of its own
498	      // under every commit it touched.
499	      const item = new vscode.TreeItem(
500	        commit.subject || '(no subject)',
501	        !sole || sessions > 1 ? vscode.TreeItemCollapsibleState.Collapsed : vscode.TreeItemCollapsibleState.None,
502	      );
503	      item.description = joinParts(
504	        commit.shortSha,
505	        noData
506	          ? NO_DATA
507	          : !sole
508	            ? `${commit.checkpointIds.length} checkpoints`
509	            : sessions > 1
510	              ? `${sessions} sessions`
511	              : row?.agent,
512	        sole && sessions === 1 ? positionText(repo, row?.sessionId, sole) : undefined,
513	        relativeTime(commit.authorTime * 1000),
514	      );
515	      item.iconPath = noData ? muted('git-commit') : new vscode.ThemeIcon('git-commit');
516	      // A commit with one checkpoint opens it. A commit with several expands instead.
517	      if (sole) item.command = openCommand(node);
518	      item.contextValue = contextValue(node, sole ? ['openable'] : []);
519	      return item;
520	    }
521	
522	    case 'checkpoint': {
523	      const { row, commit } = node;
524	      const sessions = sessionCount(row);
525	      // Under a session, the place is in that session. Elsewhere it is in the
526	      // checkpoint's own session, when it has exactly one.
527	      const within = node.sessionId ?? (sessions === 1 ? row?.sessionId : undefined);
528	      // A ULID is never shortened: sibling IDs share their leading characters.
529	      const item = new vscode.TreeItem(
530	        headline(row?.message) || node.checkpointId,
531	        sessions > 1 ? vscode.TreeItemCollapsibleState.Collapsed : vscode.TreeItemCollapsibleState.None,
532	      );
533	      const noData = node.repo.withoutData.has(node.checkpointId);
534	      item.description = joinParts(
535	        noData ? NO_DATA : node.sessionId ? undefined : sessions > 1 ? `${sessions} sessions` : row?.agent,
536	        node.position ? formatPosition(node.position) : positionText(node.repo, within, node.checkpointId),
537	        relativeTime(row?.date),
538	        commit?.shortSha,
539	      );
540	      item.iconPath = noData ? muted('bookmark') : new vscode.ThemeIcon('bookmark');
541	      item.command = openCommand(node);
542	      item.contextValue = contextValue(node, ['openable']);
543	      return item;
544	    }
545	
546	    case 'slot': {
547	      const { session } = node;
548	      const item = new vscode.TreeItem(
549	        joinParts(session.agent ?? 'Agent session', session.model),
550	        vscode.TreeItemCollapsibleState.None,
551	      );
552	      item.description = joinParts(
553	        positionText(node.repo, session.sessionId, node.checkpointId),
554	        session.tokenUsage ? `${formatTokens(totalTokens(session.tokenUsage))} tokens` : undefined,
555	      );
556	      item.iconPath = new vscode.ThemeIcon('comment-discussion');
557	      item.command = openCommand(node);
558	      item.contextValue = contextValue(node, ['openable']);
559	      return item;
560	    }
561	
562	    case 'loadMore': {
563	      const item = new vscode.TreeItem(`Load More ${node.noun}`, vscode.TreeItemCollapsibleState.None);
564	      const shown = node.shown.toLocaleString();
565	      item.description = node.scanned
566	        ? // A filtered list cannot say how many rows are left, only how far it has looked.
567	          `${shown} shown · ${node.scanned.read.toLocaleString()}${
568	            node.scanned.total === undefined ? '' : ` of ${node.scanned.total.toLocaleString()}`
569	          } read`
570	        : node.total === undefined
571	          ? `${shown} shown`
572	          : `${shown} of ${node.total.toLocaleString()} shown`;
573	      item.iconPath = new vscode.ThemeIcon('fold-down');
574	      item.command = { command: 'entire.loadMore', title: 'Load More', arguments: [node] };
575	      // The URI is how the extension learns that this row has scrolled into view.
576	      item.resourceUri = loadMoreUri(node);
577	      item.tooltip = 'More rows load when you scroll here. Click to load them now.';
578	      item.contextValue = 'loadMore';
579	      return item;
580	    }
581	
582	    case 'otherGroup': {
583	      const count = node.repo.index?.unlinkedRows().length ?? 0;
584	      const item = new vscode.TreeItem('Other Checkpoints', vscode.TreeItemCollapsibleState.Collapsed);
585	      item.description = String(count);
586	      item.iconPath = new vscode.ThemeIcon('archive');
587	      item.tooltip =
588	        'Checkpoints that no scanned commit on this branch carries, such as imported checkpoints and checkpoints from other branches.';
589	      item.contextValue = 'otherGroup';
590	      return item;
591	    }
592	
593	    case 'sessionGroup': {
594	      const item = new vscode.TreeItem(
595	        node.group === 'active' ? 'Active' : 'Recent',
596	        vscode.TreeItemCollapsibleState.Expanded,
597	      );
598	      item.contextValue = 'sessionGroup';
599	      return item;
600	    }
601	
602	    case 'session': {
603	      const { session } = node;
604	      const live = session.status === 'active' || session.status === 'idle';
605	      // The name is the one entire.com shows, for a session that Entire lists,
606	      // and otherwise the prompt that opened the session. Until either is
607	      // known, the row falls back to the latest prompt or to the newest
608	      // checkpoint's message.
609	      const item = new vscode.TreeItem(
610	        headline(session.name ?? session.lastPrompt ?? session.title) || `${session.agent ?? 'Agent'} session`,
611	        checkpointCount(session) > 0 ? vscode.TreeItemCollapsibleState.Collapsed : vscode.TreeItemCollapsibleState.None,
612	      );
613	      item.description = joinParts(
614	        session.agent,
615	        live ? session.status : undefined,
616	        checkpointCountText(session),
617	        relativeTime(session.lastActive),
618	      );
619	      item.iconPath =
620	        session.status === 'active'
621	          ? new vscode.ThemeIcon('circle-filled', new vscode.ThemeColor('charts.green'))
622	          : session.status === 'idle'
623	            ? new vscode.ThemeIcon('circle-outline')
624	            : new vscode.ThemeIcon('comment-discussion');
625	      item.command = openCommand(node);
626	      item.contextValue = contextValue(node, ['openable', 'hasTranscript']);
627	      return item;
628	    }
629	
630	    case 'trail': {
631	      const { trail, repo } = node;
632	      const hosted = repo.entireRepo;
633	      // A trail can have a branch in several repositories. The row describes the one here.
634	      const change = hosted ? trail.changes[primaryChange(trail.changes, hosted, repo.branch)] : undefined;
635	      const checkedOut = change !== undefined && hosted !== undefined && isCheckedOut(change, hosted, repo.branch);
636	      const item = new vscode.TreeItem(headline(trail.title) || `Trail ${trail.number}`, vscode.TreeItemCollapsibleState.None);
637	      item.description = joinParts(
638	        `#${trail.number}`,
639	        trail.phase ?? trail.status,
640	        change?.branch ? (checkedOut ? `${change.branch} (checked out)` : change.branch) : undefined,
641	        relativeTime(trail.lastActivityAt),
642	      );
643	      item.iconPath = trailIcon(trail, checkedOut);
644	      item.command = openCommand(node);
645	      // Trails are listed only for repositories that Entire hosts, so each has a page on the web.
646	      item.contextValue = contextValue(node, ['openable', 'web']);
647	      return item;
648	    }
649	
650	    case 'message': {
651	      const item = new vscode.TreeItem(node.text, vscode.TreeItemCollapsibleState.None);
652	      item.iconPath = new vscode.ThemeIcon('info');
653	      item.contextValue = 'message';
654	      return item;
655	    }
656	  }
657	}
