1	import * as vscode from 'vscode';
2	import type { CommitRecord } from '../../core/trailers';
3	import type { DetailTarget } from '../../shared/protocol';
4	import { LISTS, type RepoContext, type RepoManager } from '../repoManager';
5	import { nodeId, paged, tooltip, treeItem, type Node } from './nodes';
6	import { RowRegistry } from './rowRegistry';
7	
8	/** Pages a list may grow by to bring one row onto it. */
9	export const MAX_PAGES_TO_REACH_A_ROW = 20;
10	
11	/** Session slots of one checkpoint, loaded from the CLI the first time the row expands. */
12	export async function slotNodes(
13	  manager: RepoManager,
14	  repo: RepoContext,
15	  checkpointId: string,
16	  commit: CommitRecord | undefined,
17	  parentId: string,
18	): Promise<Node[]> {
19	  const detail = await manager.detail(repo, checkpointId);
20	  if (!detail.ok) {
21	    return [{ kind: 'message', id: `${parentId}|error`, text: detail.failure.message }];
22	  }
23	  if (detail.value.sessions.length === 0) {
24	    return [{ kind: 'message', id: `${parentId}|empty`, text: 'This checkpoint has no recorded sessions.' }];
25	  }
26	  return detail.value.sessions.map(
27	    (session): Node => ({
28	      kind: 'slot',
29	      repo,
30	      checkpointId,
31	      session,
32	      parentId,
33	      ...(commit ? { commit } : {}),
34	    }),
35	  );
36	}
37	
38	/**
39	 * Commits on the current branch that carry checkpoints.
40	 *
41	 * Git supplies every row, so the list is complete without the CLI. CLI rows
42	 * add the agent where they exist. Rows appear a page at a time, and history
43	 * is scanned further back only when a page needs it.
44	 */
45	export class CheckpointsTree implements vscode.TreeDataProvider<Node>, vscode.Disposable {
46	  private readonly changed = new vscode.EventEmitter<Node | undefined>();
47	  readonly onDidChangeTreeData = this.changed.event;
48	  private readonly subscription: vscode.Disposable;
49	  /** One object for each row, so that `TreeView.reveal` finds the row it is given. */
50	  private readonly rows = new RowRegistry();
51	
52	  constructor(private readonly manager: RepoManager) {
53	    this.subscription = manager.onDidChange(() => this.changed.fire(undefined));
54	  }
55	
56	  dispose(): void {
57	    this.subscription.dispose();
58	    this.changed.dispose();
59	  }
60	
61	  getTreeItem(node: Node): vscode.TreeItem {
62	    return treeItem(node);
63	  }
64	
65	  /** Called when a row is hovered, to fill in the tooltip that `getTreeItem` leaves out. */
66	  resolveTreeItem(item: vscode.TreeItem, node: Node): vscode.TreeItem {
67	    const text = tooltip(node);
68	    if (text) item.tooltip = text;
69	    return item;
70	  }
71	
72	  getParent(node: Node): Node | undefined {
73	    return this.rows.parentOf(node);
74	  }
75	
76	  async getChildren(node?: Node): Promise<Node[]> {
77	    if (!node) this.rows.keepOnly(this.manager.repos.map((repo) => repo.root));
78	    return this.rows.adopt(await this.listChildren(node), node);
79	  }
80	
81	  /**
82	   * The row to select while a detail tab shows `target`: the commit that
83	   * carries the checkpoint, the checkpoint's own row under a commit that
84	   * carries several, or its row under Other Checkpoints. With `slot`, it is
85	   * the row of the target's session under that, for a checkpoint that holds
86	   * several sessions.
87	   *
88	   * A row beyond the end of its list is brought onto it: the list grows by
89	   * as many pages as it takes. Undefined when the view has no row for the
90	   * checkpoint.
91	   */
92	  async find(target: DetailTarget, options: { slot?: boolean } = {}): Promise<Node | undefined> {
93	    const repo = this.manager.repoFor(target.repoRoot);
94	    const checkpointId = target.checkpointId;
95	    if (!repo?.enabled || !repo.index || !checkpointId || this.manager.viewState !== 'ready') return undefined;
96	    const top = async (): Promise<Node[]> => {
97	      const roots = await this.getChildren();
98	      const own = roots.find((node) => node.kind === 'repo' && node.repo === repo);
99	      return own ? this.getChildren(own) : roots;
100	    };
101	
102	    let row: Node | undefined;
103	    const carriers = repo.index.commitsFor(checkpointId);
104	    const commit = carriers.find((carrier) => carrier.sha === target.commitSha) ?? carriers[0];
105	    if (commit) {
106	      // The commit has been scanned, so only the number of rows on show stands between it and the list.
107	      for (let pages = 0; pages < MAX_PAGES_TO_REACH_A_ROW; pages += 1) {
108	        const at = repo.index?.commits.indexOf(commit) ?? -1;
109	        if (at < 0) return undefined;
110	        if (at < repo.limit(LISTS.commits)) break;
111	        await this.manager.showMore(repo, LISTS.commits);
112	      }
113	      const commitRow = (await top()).find((node) => node.kind === 'commit' && node.commit.sha === commit.sha);
114	      if (!commitRow) return undefined;
115	      row =
116	        commit.checkpointIds.length > 1
117	          ? (await this.getChildren(commitRow)).find((node) => node.kind === 'checkpoint' && node.checkpointId === checkpointId)
118	          : commitRow;
119	    } else {
120	      const at = repo.index.unlinkedRows().findIndex((unlinked) => unlinked.checkpointId === checkpointId);
121	      if (at < 0) return undefined;
122	      for (let pages = 0; pages < MAX_PAGES_TO_REACH_A_ROW && at >= repo.limit(LISTS.otherCheckpoints); pages += 1) {
123	        await this.manager.showMore(repo, LISTS.otherCheckpoints);
124	      }
125	      const group = (await top()).find((node) => node.kind === 'otherGroup');
126	      row = group
127	        ? (await this.getChildren(group)).find((node) => node.kind === 'checkpoint' && node.checkpointId === checkpointId)
128	        : undefined;
129	    }
130	    if (!row || !options.slot || !target.sessionId) return row;
131	    const slot = (await this.getChildren(row)).find(
132	      (node) => node.kind === 'slot' && node.session.sessionId === target.sessionId,
133	    );
134	    return slot ?? row;
135	  }
136	
137	  private async listChildren(node?: Node): Promise<Node[]> {
138	    if (!node) {
139	      if (this.manager.viewState !== 'ready') return [];
140	      const repos = this.manager.enabledRepos;
141	      if (repos.length === 1 && repos[0]) return this.repoChildren(repos[0]);
142	      return repos.map((repo): Node => ({ kind: 'repo', repo }));
143	    }
144	
145	    switch (node.kind) {
146	      case 'repo':
147	        return this.repoChildren(node.repo);
148	      case 'commit': {
149	        const { commit, repo } = node;
150	        const parentId = nodeId(node);
151	        const [first, ...rest] = commit.checkpointIds;
152	        if (first && rest.length === 0) return slotNodes(this.manager, repo, first, commit, parentId);
153	        return commit.checkpointIds.map((checkpointId): Node => {
154	          const row = repo.index?.row(checkpointId);
155	          return { kind: 'checkpoint', repo, checkpointId, commit, parentId, ...(row ? { row } : {}) };
156	        });
157	      }
158	      case 'checkpoint':
159	        return slotNodes(this.manager, node.repo, node.checkpointId, node.commit, nodeId(node));
160	      case 'otherGroup': {
161	        const parentId = nodeId(node);
162	        return paged(
163	          node.repo,
164	          LISTS.otherCheckpoints,
165	          'Checkpoints',
166	          node.repo.index?.unlinkedRows() ?? [],
167	          (row): Node => ({ kind: 'checkpoint', repo: node.repo, checkpointId: row.checkpointId, row, parentId }),
168	        );
169	      }
170	      default:
171	        return [];
172	    }
173	  }
174	
175	  private repoChildren(repo: RepoContext): Node[] {
176	    const index = repo.index;
177	    if (!index) return [];
178	    const nodes = paged(
179	      repo,
180	      LISTS.commits,
181	      'Checkpoints',
182	      index.commits,
183	      (commit): Node => ({ kind: 'commit', repo, commit }),
184	      { moreToRead: !index.exhausted },
185	    );
186	    if (index.unlinkedRows().length > 0) nodes.push({ kind: 'otherGroup', repo });
187	    return nodes;
188	  }
189	}
