369	      if (stale()) return;
370	      if (!paths.ok) {
371	        this.log.info(`${folder.uri.fsPath}: ${paths.failure.message} ${paths.failure.detail ?? ''}`.trim());
372	        continue;
373	      }
374	      if (repos.some((repo) => repo.root === paths.value.root)) continue;
375	      const existing = previous.get(paths.value.root);
376	      repos.push(existing ?? new RepoContext(paths.value));
377	    }
378	    this.replaceRepos(repos);
379	    if (repos.length === 0) {
