385	    const configured = vscode.workspace.getConfiguration('entire').get<string>('cliPath');
386	    const located = await locateCli(configured, {
387	      env: process.env,
388	      platform: process.platform,
389	      homedir: os.homedir(),
390	      isExecutable: isExecutableFile,
391	      probeLoginShell: loginShellProbe(this.exec, process.env, cwd),
392	    });
393	    if (stale()) return;
394	    if (!located) {
395	      this.cli = undefined;
396	      this.log.warn(
397	        configured?.trim()
398	          ? `entire.cliPath is set to "${configured}", but no executable exists there.`
399	          : 'The Entire CLI was not found on PATH, in common install locations, or through the login shell.',
400	      );
401	      this.setState('cliMissing');
402	      return;
403	    }
404	
405	    const cli = new EntireCli(located.path, this.exec, this.cliLane, (line) => this.log.info(line));
406	    const version = await cli.version(cwd);
407	    if (stale()) return;
408	    if (!version.ok) {
409	      this.cli = undefined;
410	      this.log.warn(`${located.path}: ${version.failure.message} ${version.failure.detail ?? ''}`.trim());
411	      this.setState('cliMissing');
412	      return;
413	    }
414	    this.cliVersion = version.value;
415	    this.log.info(`Using Entire CLI ${version.value.raw} at ${located.path} (found through ${located.source}).`);
416	    if (!isSupportedVersion(version.value)) {
417	      this.cli = undefined;
418	      this.log.warn(`Entire CLI ${version.value.raw} is older than the required ${MIN_CLI_VERSION_TEXT}.`);
419	      this.setState('cliTooOld');
420	      return;
421	    }
422	    this.cli = cli;
423	
424	    await Promise.all(repos.map((repo) => this.loadStatus(repo)));
425	    if (stale()) return;
426	    if (options.manual) {
427	      for (const repo of repos) {
428	        repo.trailUrls.clear();
429	        repo.trailMemory.clear();
430	        // Only lists the Trails view has already asked for. Nothing waits for them.
431	        if (repo.entireRepo && repo.trails) void this.loadTrails(repo);
432	      }
433	    }
434	    if (this.enabledRepos.length === 0) {
435	      this.setState('notEnabled');
436	      return;
437	    }
438	
439	    await Promise.all(
440	      this.enabledRepos.map(async (repo) => {
441	        repo.details.clear();
442	        repo.withoutData.clear();
443	        await this.loadGit(repo, { force: true });
444	        this.scheduleEnrichment(repo, { immediate: true });
445	        if (options.manual && repo.sessionRows !== undefined) await this.loadSessionRows(repo);
446	        if (options.manual && repo.remoteSessions !== undefined) {
447	          // Only a list the Sessions view has already asked for. Nothing waits for it.
448	          repo.remoteCheckpoints.clear();
449	          void this.loadRemoteSessions(repo);
450	        }

