1002	  detail(repo: RepoContext, checkpointId: string, signal?: AbortSignal): Promise<Result<CheckpointDetail>> {
1003	    const cli = this.cli;
1004	    if (!cli) return Promise.resolve(fail('cliMissing', 'The Entire CLI is not available.'));
1005	    const cached = repo.details.get(checkpointId);
1006	    if (cached && Date.now() - cached.at < DETAIL_TTL_MS) {
1007	      // Refresh the entry's position so the least recently used one is evicted first.
1008	      repo.details.delete(checkpointId);
1009	      repo.details.set(checkpointId, cached);
1010	      return cached.result;
1011	    }
1012	    const result = cli.explainCheckpoint(repo.root, checkpointId, signal).then((outcome) => {
1013	      const missing = !outcome.ok && outcome.failure.kind === 'notFound';
1014	      if (!outcome.ok) {
1015	        if (!missing && repo.details.get(checkpointId)?.result === result) repo.details.delete(checkpointId);
