1020	      // Rows for the checkpoint say whether it has data, so they are redrawn when that is learned.
1021	      if (missing !== repo.withoutData.has(checkpointId) && (missing || outcome.ok)) {
1022	        if (missing) repo.withoutData.add(checkpointId);
1023	        else repo.withoutData.delete(checkpointId);
1024	        this.changed.fire();
1025	      }
1026	      return outcome;
1027	    });
1028	    repo.details.delete(checkpointId);
1029	    repo.details.set(checkpointId, { at: Date.now(), result });
