1037	  /** Sessions for the Sessions view: running ones first, then the rest by recency. */
1038	  sessions(repo: RepoContext): { active: SessionEntry[]; recent: SessionEntry[] } {
1039	    const entries = new Map<string, SessionEntry>();
1040	    const entry = (sessionId: string): SessionEntry => {
1041	      let found = entries.get(sessionId);
1042	      if (!found) {
1043	        found = { sessionId, checkpoints: [] };
1044	        entries.set(sessionId, found);
1045	      }
1046	      return found;
1047	    };
1048	
1049	    for (const indexed of repo.index?.sessions() ?? []) {
1050	      const target = entry(indexed.sessionId);
1051	      target.checkpoints = [...indexed.checkpoints];
1052	      if (indexed.mayHaveEarlier) target.mayHaveEarlier = true;
1053	      if (indexed.agent) target.agent = indexed.agent;
1054	      if (indexed.lastDate) target.lastActive = indexed.lastDate;
1055	      const title = indexed.checkpoints[0]?.message;
1056	      if (title) target.title = title;
1057	    }
1058	
1059	    for (const row of repo.sessionRows ?? []) {
1060	      const target = entry(row.sessionId);
1061	      target.local = row;
1062	      if (row.agent) target.agent = row.agent;
1063	      if (row.model) target.model = row.model;
1064	      if (row.status) target.status = row.status;
1065	      if (row.lastPrompt) target.lastPrompt = row.lastPrompt;
1066	      const lastActive = row.lastActive ?? row.endedAt ?? row.startedAt;
1067	      if (lastActive && (!target.lastActive || Date.parse(lastActive) > Date.parse(target.lastActive))) {
1068	        target.lastActive = lastActive;
1069	      }
1070	      if (row.lastCheckpointId && !target.checkpoints.some((cp) => cp.checkpointId === row.lastCheckpointId)) {
1071	        target.checkpoints.push({ checkpointId: row.lastCheckpointId });
1072	      }
1073	    }
1074	
1075	    for (const live of repo.status?.activeSessions ?? []) {
1076	      if (!live.sessionId) continue;
1077	      const target = entry(live.sessionId);
1078	      target.status = live.status ?? 'active';
1079	      if (live.agent) target.agent = live.agent;
1080	      if (live.model) target.model = live.model;
1081	      if (live.branch) target.branch = live.branch;
1082	    }
1083	
1084	    // Entire's list names its sessions, counts their checkpoints, and adds
1085	    // the ones this clone has no data for, such as those of other branches.
1086	    for (const listed of repo.remoteSessions?.sessions.values() ?? []) {
1087	      const target = entry(listed.sessionId);
1088	      if (listed.name) target.name = listed.name;
1089	      if (listed.prompt && listed.prompt !== listed.name) target.opening = listed.prompt;
1090	      if (listed.agent) target.agent ??= listed.agent;
1091	      if (listed.model) target.model ??= listed.model;
1092	      if (listed.checkpointCount !== undefined) target.listedCheckpoints = listed.checkpointCount;
1093	      const lastActive = listed.lastActivityAt ?? listed.startedAt;
1094	      if (lastActive && instant(lastActive) > instant(target.lastActive)) target.lastActive = lastActive;
1095	    }
1096	    for (const [sessionId, read] of repo.remoteCheckpoints) {
1097	      const target = entries.get(sessionId);
1098	      if (!target || !read.checkpoints) continue;
1099	      const known = new Set(target.checkpoints.map((checkpoint) => checkpoint.checkpointId));
1100	      for (const checkpoint of read.checkpoints) {
1101	        if (known.has(checkpoint.checkpointId)) continue;
1102	        target.checkpoints.push({
1103	          checkpointId: checkpoint.checkpointId,
1104	          ...(checkpoint.date ? { date: checkpoint.date } : {}),
1105	          ...(checkpoint.message ? { message: checkpoint.message } : {}),
1106	        });
1107	      }
1108	      target.checkpoints.sort((a, b) => instant(b.date) - instant(a.date));
1109	      target.checkpointsFromEntire = true;
1110	      // Entire lists the session from its start.
1111	      delete target.mayHaveEarlier;
1112	    }
1113	
1114	    const byRecency = (a: SessionEntry, b: SessionEntry): number => instant(b.lastActive) - instant(a.lastActive);
1115	    const all = [...entries.values()];
1116	    for (const session of all) {
1117	      const opening = repo.sessionNames.get(session.sessionId)?.name;
1118	      if (!opening) continue;
1119	      // The opening prompt names a session that Entire has not named.
1120	      if (!session.name) session.name = opening;
1121	      else if (session.name !== opening) session.opening ??= opening;
1122	    }
1123	    const isLive = (session: SessionEntry): boolean => session.status === 'active' || session.status === 'idle';
1124	    return {
1125	      active: all.filter(isLive).sort(byRecency),
1126	      recent: all.filter((session) => !isLive(session)).sort(byRecency),
1127	    };
1128	  }
