1	/**
2	 * Shapes of the Entire CLI's JSON output, read tolerantly.
3	 *
4	 * The CLI is pre-1.0 and adds fields between releases, so these readers take
5	 * what they recognize, default what is missing, and drop entries that lack an
6	 * ID instead of rejecting the whole payload.
7	 */
8	import { isTrailId } from './trails';
9	
10	export interface ActiveSession {
