30	  /** The session the row's `agent` and `message` describe. */
31	  sessionId?: string;
32	  agent?: string;
33	  date?: string;
34	  /**
35	   * The commit subject when a commit on the branch carries the checkpoint,
36	   * and otherwise the latest prompt of its session.
37	   */
38	  message?: string;
39	  sessionIds: string[];
40	  sessionCount?: number;
41	}
42	
43	export interface TokenUsage {
