95	  cacheRead: number;
96	  cacheWrite: number;
97	  output: number;
98	}
99	
100	/** One row of `entire session list --json`. */
101	export interface SessionRow {
102	  sessionId: string;
103	  agent?: string;
104	  model?: string;
105	  /** `active`, `idle`, or `ended`. */
106	  status?: string;
107	  kind?: string;
