113	  pendingTurns?: number;
114	  lastCheckpointId?: string;
115	  tokens?: SessionTokens;
116	  lastPrompt?: string;
117	}
118	
119	/** One CI run on the head commit of a change. */
120	export interface TrailCheckRun {
121	  name: string;
122	  /** `queued`, `in_progress`, or `completed`. */
123	  status?: string;
124	  /** Set once the run completes: `success`, `failure`, `skipped`, and so on. */
125	  conclusion?: string;
126	  detailsUrl?: string;
127	  appName?: string;
128	}
129	
130	/** One condition a change has to meet before it can merge. */
131	export interface TrailGate {
132	  key: string;
133	  blocking: boolean;
