234	type Json = Record<string, unknown>;
235	
236	function isObject(value: unknown): value is Json {
237	  return typeof value === 'object' && value !== null && !Array.isArray(value);
238	}
239	
240	function str(value: unknown): string | undefined {
241	  return typeof value === 'string' && value !== '' ? value : undefined;
242	}
243	
244	function num(value: unknown): number | undefined {
245	  return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
246	}
247	
248	function strings(value: unknown): string[] {
249	  return Array.isArray(value) ? value.filter((item): item is string => typeof item === 'string' && item !== '') : [];
250	}
251	
252	function objects(value: unknown): Json[] {
253	  return Array.isArray(value) ? value.filter(isObject) : [];
254	}
255	
256	/** Copies only the defined entries, so optional fields stay absent instead of `undefined`. */
257	function compact<T extends object>(value: { [K in keyof T]: T[K] | undefined }): T {
258	  const out: Record<string, unknown> = {};
259	  for (const [key, entry] of Object.entries(value)) {
260	    if (entry !== undefined) out[key] = entry;
261	  }
262	  return out as T;
263	}
264	
265	export function readStatus(value: unknown): StatusInfo | undefined {
266	  if (!isObject(value) || typeof value.enabled !== 'boolean') return undefined;
267	  return compact<StatusInfo>({
268	    enabled: value.enabled,
269	    error: str(value.error),
270	    agents: strings(value.agents),
271	    activeSessions: objects(value.active_sessions).map((session) =>
272	      compact<ActiveSession>({
273	        sessionId: str(session.session_id),
274	        agent: str(session.agent),
275	        model: str(session.model),
276	        status: str(session.status),
277	        branch: str(session.branch),
278	        worktreePath: str(session.worktree_path),
279	      }),
280	    ),
281	  });
282	}
283	
284	export function readCheckpointRows(value: unknown): CheckpointRow[] | undefined {
285	  if (!Array.isArray(value)) return undefined;
286	  const rows: CheckpointRow[] = [];
287	  for (const item of objects(value)) {
288	    const checkpointId = str(item.checkpoint_id);
289	    if (!checkpointId) continue;
290	    const sessionId = str(item.session_id);
291	    const sessionIds = strings(item.session_ids);
292	    if (sessionId && !sessionIds.includes(sessionId)) sessionIds.unshift(sessionId);
293	    rows.push(
294	      compact<CheckpointRow>({
295	        checkpointId,
296	        sessionId,
297	        agent: str(item.agent),
298	        date: str(item.date),
299	        message: str(item.message),
300	        sessionIds,
301	        sessionCount: num(item.session_count),
302	      }),
303	    );
304	  }
305	  return rows;
