311	    input: num(value.input_tokens) ?? 0,
312	    cacheCreation: num(value.cache_creation_tokens) ?? 0,
313	    cacheRead: num(value.cache_read_tokens) ?? 0,
314	    output: num(value.output_tokens) ?? 0,
315	    apiCalls: num(value.api_call_count) ?? 0,
