319	function readSummary(value: unknown): SessionSummaryText | undefined {
320	  if (!isObject(value)) return undefined;
321	  const summary = compact<SessionSummaryText>({ intent: str(value.intent), outcome: str(value.outcome) });
322	  return summary.intent || summary.outcome ? summary : undefined;
323	}
