325	export function readCheckpointDetail(value: unknown): CheckpointDetail | undefined {
326	  if (!isObject(value)) return undefined;
327	  const checkpointId = str(value.checkpoint_id);
328	  if (!checkpointId) return undefined;
329	  const sessions = objects(value.sessions).map((session, position) =>
330	    compact<CheckpointSession>({
331	      index: num(session.index) ?? position,
332	      sessionId: str(session.session_id),
333	      agent: str(session.agent),
334	      model: str(session.model),
335	      kind: str(session.kind),
336	      createdAt: str(session.created_at),
337	      filesTouched: strings(session.files_touched),
338	      tokenUsage: readTokenUsage(session.token_usage),
339	      summary: readSummary(session.summary),
340	    }),
341	  );
342	  const tasks: CheckpointTask[] = [];
343	  for (const task of objects(value.tasks)) {
344	    const toolUseId = str(task.tool_use_id);
345	    if (!toolUseId) continue;
346	    tasks.push(
347	      compact<CheckpointTask>({
348	        toolUseId,
349	        agentId: str(task.agent_id),
350	        subagentType: str(task.subagent_type),
351	        description: str(task.task_description),
352	        startedAt: str(task.started_at),
353	        completedAt: str(task.completed_at),
354	      }),
355	    );
356	  }
357	  return compact<CheckpointDetail>({
358	    checkpointId,
359	    branch: str(value.branch),
360	    promptCount: num(value.checkpoints_count),
361	    filesTouched: strings(value.files_touched),
362	    sessions,
363	    tasks,
364	    partial: value.partial === true,
365	  });
