368	function readSessionTokens(value: unknown): SessionTokens | undefined {
369	  if (!isObject(value)) return undefined;
370	  return {
371	    total: num(value.total) ?? 0,
372	    input: num(value.input) ?? 0,
373	    cacheRead: num(value.cache_read) ?? 0,
374	    cacheWrite: num(value.cache_write) ?? 0,
375	    output: num(value.output) ?? 0,
