377	}
378	
379	export function readSessionRows(value: unknown): SessionRow[] | undefined {
380	  if (!Array.isArray(value)) return undefined;
381	  const rows: SessionRow[] = [];
382	  for (const item of objects(value)) {
383	    const sessionId = str(item.session_id);
384	    if (!sessionId) continue;
385	    rows.push(
386	      compact<SessionRow>({
387	        sessionId,
388	        agent: str(item.agent),
389	        model: str(item.model),
390	        status: str(item.status),
391	        kind: str(item.kind),
392	        startedAt: str(item.started_at),
393	        endedAt: str(item.ended_at),
394	        lastActive: str(item.last_active),
395	        turns: num(item.turns),
396	        pendingTurns: num(item.pending_turns),
397	        lastCheckpointId: str(item.last_checkpoint_id),
398	        tokens: readSessionTokens(item.tokens),
399	        lastPrompt: str(item.last_prompt),
400	      }),
