406	/** Names from a list whose entries are strings or objects with a `name`. */
407	function names(value: unknown): string[] {
408	  if (!Array.isArray(value)) return [];
409	  const out: string[] = [];
410	  for (const item of value) {
411	    const name = isObject(item) ? (str(item.name) ?? str(item.label)) : str(item);
412	    if (name) out.push(name);
413	  }
414	  return out;
415	}
416	
417	function readMergeability(value: unknown): TrailMergeability | undefined {
418	  if (!isObject(value)) return undefined;
419	  const checks = isObject(value.checks) ? value.checks : {};
420	  const runs: TrailCheckRun[] = [];
421	  for (const run of objects(checks.runs)) {
422	    const name = str(run.name);
423	    if (!name) continue;
424	    runs.push(
425	      compact<TrailCheckRun>({
426	        name,
427	        status: str(run.status),
428	        conclusion: str(run.conclusion),
429	        detailsUrl: str(run.details_url),
430	        appName: str(run.app_name),
431	      }),
432	    );
433	  }
434	  const gates: TrailGate[] = [];
435	  for (const gate of objects(value.gates)) {
436	    const key = str(gate.gate_key) ?? str(gate.gate_type);
437	    if (!key) continue;
438	    gates.push(
439	      compact<TrailGate>({
440	        key,
441	        blocking: gate.blocking === true,
442	        status: str(gate.status),
443	        rationale: str(gate.rationale),
444	        findingCount: num(gate.finding_count),
445	      }),
446	    );
447	  }
448	  return compact<TrailMergeability>({
449	    mergeable: value.mergeable === true,
450	    headSha: str(value.head_sha),
451	    conflictStatus: str(value.conflict_status),
452	    checksAvailability: str(checks.availability),
453	    checks: runs,
454	    gates,
455	  });
456	}
457	
458	function readTrailChanges(value: unknown): TrailChange[] {
459	  const changes: TrailChange[] = [];
460	  for (const change of objects(value)) {
461	    const repository = str(change.repository);
462	    const number = num(change.number);
463	    if (!repository || number === undefined) continue;
464	    changes.push(
465	      compact<TrailChange>({
466	        repository,
467	        number,
468	        title: str(change.title),
469	        status: str(change.status),
470	        branch: str(change.branch),
471	        base: str(change.base),
472	        hasCodeChanges: change.hasCodeChanges === true,
473	        updatedAt: str(change.updatedAt),
474	        url: str(change.url),
475	        mergeability: readMergeability(change.mergeability),
476	      }),
477	    );
478	  }
479	  return changes;
480	}
481	
482	function readTrailSummary(item: Json): TrailSummary | undefined {
483	  const number = num(item.number);
484	  if (number === undefined) return undefined;
485	  return compact<TrailSummary>({
486	    number,
487	    // Kept only in the form the CLI is known to accept. Without it, calls name the trail by number.
488	    id: isTrailId(item.id) ? item.id : undefined,
489	    title: str(item.title) ?? `Trail ${number}`,
490	    body: str(item.body),
491	    status: str(item.status),
492	    phase: str(item.phase),
493	    type: str(item.type),
494	    priority: str(item.priority),
495	    assignees: strings(item.assignees),
496	    createdAt: str(item.createdAt),
497	    lastActivityAt: str(item.lastActivityAt) ?? str(item.updatedAt),
498	    closedAt: str(item.closedAt),
499	    changes: readTrailChanges(item.changes),
500	  });
501	}
502	
503	export function readTrailPage(value: unknown): TrailPage | undefined {
504	  if (!isObject(value) || !Array.isArray(value.items)) return undefined;
505	  const trails: TrailSummary[] = [];
506	  for (const item of objects(value.items)) {
507	    const trail = readTrailSummary(item);
508	    if (trail) trails.push(trail);
509	  }
510	  // The CLI reports one total per group, and one group when the list is not grouped.
511	  const groups = objects(value.groupTotals).length > 0 ? objects(value.groupTotals) : objects(value.groups);
512	  const totals = groups.map((group) => num(group.totalCount)).filter((count) => count !== undefined);
513	  return compact<TrailPage>({
514	    trails,
515	    nextPageToken: str(value.nextPageToken),
516	    total: totals.length > 0 ? totals.reduce((sum, count) => sum + count, 0) : undefined,
517	  });
518	}
519	
520	export function readTrailDetail(value: unknown): TrailDetail | undefined {
521	  if (!isObject(value)) return undefined;
522	  const summary = readTrailSummary(value);
523	  if (!summary) return undefined;
524	  const project = isObject(value.project) ? value.project : {};
525	  return compact<TrailDetail>({ ...summary, url: str(value.url), projectName: str(project.name) });
526	}
527	
528	function readActor(value: unknown): string | undefined {
529	  if (!isObject(value)) return undefined;
530	  const identity = isObject(value.identity) ? value.identity : {};
531	  return str(identity.display_name) ?? str(value.label) ?? str(value.login);
532	}
533	
534	export function readTrailTimeline(value: unknown): TrailTimeline | undefined {
535	  if (!isObject(value) || !Array.isArray(value.items)) return undefined;
536	  const events: TrailEvent[] = [];
537	  for (const item of objects(value.items)) {
538	    const kind = str(item.kind);
539	    if (!kind) continue;
540	    events.push(
541	      compact<TrailEvent>({
542	        kind,
543	        actor: readActor(item.actor),
544	        occurredAt: str(item.occurredAt),
545	        title: str(item.title),
546	        commitSha: str(item.commitSha),
547	        additions: num(item.additions),
548	        deletions: num(item.deletions),
549	        filesChanged: num(item.filesChanged),
550	        checkpointCount: num(item.checkpointCount),
551	        agents: names(item.agents),
552	        findingCount: num(item.findingCount),
553	      }),
554	    );
555	  }
556	  return compact<TrailTimeline>({
557	    events,
558	    nextPageToken: str(value.nextPageToken),
559	    commitCount: num(value.commitCount),
560	    incomplete: value.incomplete === true,
561	  });
562	}
563	
564	/** Total tokens for a checkpoint session, counting cache reads and writes. */
565	export function totalTokens(usage: TokenUsage): number {
566	  return usage.input + usage.cacheCreation + usage.cacheRead + usage.output;
567	}
