17	
18	function isNode(value: unknown): value is Node {
19	  return typeof value === 'object' && value !== null && typeof (value as { kind?: unknown }).kind === 'string';
20	}
21	
22	export function registerCommands(
23	  manager: RepoManager,
24	  panels: PanelManager,
25	  actions: Actions,
26	  log: vscode.LogOutputChannel,
27	  brain: BrainService,
28	): vscode.Disposable[] {
29	  /** Registers a command that acts on a tree row and ignores calls without one. */
30	  const onNode = (command: string, handler: (node: Node) => unknown): vscode.Disposable =>
31	    vscode.commands.registerCommand(command, (node?: unknown) => {
32	      if (isNode(node)) return handler(node);
33	      return undefined;
34	    });
35	
36	  /** The view a row is in, which then follows the tab the row opens. */
37	  const originOf = (node: Node): { origin?: DetailView } => {
38	    const origin = detailViewOf(node);
39	    return origin ? { origin } : {};
40	  };
41	
42	  const pickWebRepo = async (): Promise<RepoContext | undefined> => {
43	    const repos = manager.repos.filter((repo) => repo.entireRepo !== undefined);
44	    if (repos.length <= 1) return repos[0];
45	    const pick = await vscode.window.showQuickPick(
46	      repos.map((repo) => ({ label: repo.name, description: repo.root, repo })),
47	      { placeHolder: 'Select a repository to open on entire.com' },
48	    );
49	    return pick?.repo;
50	  };
51	
52	  /** The repository whose brain to show. Entire has to be enabled in it. */
53	  const pickEnabledRepo = async (): Promise<RepoContext | undefined> => {
54	    const repos = manager.enabledRepos;
55	    if (repos.length <= 1) return repos[0];
56	    const pick = await vscode.window.showQuickPick(
57	      repos.map((repo) => ({ label: repo.name, description: repo.root, repo })),
58	      { placeHolder: 'Select a repository to show the brain graph of' },
59	    );
60	    return pick?.repo;
61	  };
62	
63	  /**
64	   * Says why the brain graph did not open. Installing the plugin and
65	   * building a brain are the user's to do, in a terminal, so the message
66	   * hands over the command and the extension runs neither.
67	   */
68	  const reportBrain = (outcome: BrainOutcome): void => {
69	    const offer = (message: string, command: string): void => {
70	      void vscode.window.showInformationMessage(message, 'Copy Command').then((choice) => {
71	        if (choice === 'Copy Command') void actions.copy(command, command);
72	      });
73	    };
74	    if (outcome.kind === 'pluginMissing') {
75	      offer(
76	        'The brain graph needs the entire-brain plugin. Run "entire plugin install brain" in a terminal, then try again.',
77	        'entire plugin install brain',
78	      );
79	    } else if (outcome.kind === 'noBrain') {
