1	// Runs inside a VS Code extension host, in the same window as extension.test.cjs.
2	// See .vscode-test.mjs for the fixture repository, whose origin uses the
3	// entire:// scheme, and for what the fake Entire CLI replies to trail calls.
4	const assert = require('node:assert/strict');
5	const fs = require('node:fs');
6	const vscode = require('vscode');
7	
8	const fixture = JSON.parse(fs.readFileSync(process.env.ENTIRE_TEST_FIXTURE, 'utf8'));
9	
10	/** Every fake CLI invocation so far, as "arg arg arg" strings. */
11	function invocations() {
12	  return fs
13	    .readFileSync(fixture.logFile, 'utf8')
14	    .split('\n')
15	    .filter(Boolean)
16	    .map((line) => JSON.parse(line).join(' '));
17	}
18	const calls = (prefix) => invocations().filter((call) => call.startsWith(prefix));
19	
20	async function until(check, label, timeoutMs = 30_000) {
21	  const deadline = Date.now() + timeoutMs;
22	  for (;;) {
23	    const value = await check();
24	    if (value) return value;
25	    if (Date.now() > deadline) throw new Error(`Timed out waiting for ${label}`);
26	    await new Promise((resolve) => setTimeout(resolve, 50));
27	  }
28	}
29	
30	function label(item) {
31	  return typeof item.label === 'string' ? item.label : item.label.label;
32	}
33	
34	suite('Entire trails', () => {
35	  /** @type {import('../../src/extension').EntireTestApi} */
36	  let api;
37	  let repo;
38	
39	  const rows = () => api.trailsTree.getChildren();
40	  const trailRows = () => rows().filter((node) => node.kind === 'trail');
41	  const loadMoreRow = () => rows().find((node) => node.kind === 'loadMore');
42	  const numbers = () => trailRows().map((node) => node.trail.number);
43	  const rowOf = (number) => trailRows().find((node) => node.trail.number === number);
44	  /** True once nothing about the view is still being read. A trail is drawn in stages. */
45	  const settled = (view) => !view.partial && !view.timelinePending && !view.refreshing;
46	  /**
47	   * Waits for a trail panel to show a trail that passes `check`, and returns a
48	   * copy of what it shows then. Unless `stage` is set, it waits for the whole
49	   * trail: the host fills in the view it hands out as the reads come back.
50	   */
51	  const viewOf = (controller, check, what, { stage = false } = {}) =>
52	    until(() => {
53	      const snapshot = controller?.snapshot();
54	      if (!snapshot || !('view' in snapshot) || !(stage || settled(snapshot.view)) || !check(snapshot)) return undefined;
55	      return JSON.parse(JSON.stringify(snapshot));
56	    }, what);
57	  const panelOn = (check, what, options) => viewOf(api.panels.currentTrail, check, what, options);
58	  const showOf = (number) => `trail show ${fixture.trailIds[number]} --project gh/acme --json`;
59	  const timelineOf = (of) => `trail timeline ${of} --project gh/acme --limit 50 --json`;
60	  /** The fake CLI's usual reply to a call, changed. */
61	  const changed = (call, changes) => ({ [call]: { ...fixture.scenario[call], ...changes } });
62	  const timelineTexts = (view) => view.timeline.events.map((event) => event.text);
63	  /** Changes what the fake CLI replies from now on. */
64	  const reply = (changes) => fs.writeFileSync(fixture.scenarioFile, JSON.stringify({ ...fixture.scenario, ...changes }));
65	
66	  suiteSetup(async () => {
67	    const extension = vscode.extensions.getExtension('entire.entire');
68	    assert.ok(extension, 'the extension is installed in the test host');
69	    api = await extension.activate();
70	    await until(() => api.manager.viewState === 'ready', 'the first load');
71	    repo = api.manager.repoFor(fixture.root);
72	    assert.ok(repo, 'the fixture repository is open');
73	  });
74	
75	  suiteTeardown(() => reply({}));
76	
77	  test('offers trails for a repository whose origin uses entire://', () => {
78	    assert.deepEqual(repo.entireRepo, { forge: 'gh', owner: 'acme', repo: 'widget' });
79	    assert.deepEqual(api.manager.trailRepos, [repo]);
80	  });
81	
82	  test('reads the first page of open trails when the Trails view is shown', async () => {
83	    // The suite before this one may have opened the Entire sidebar already,
84	    // which shows this view. states.test.cjs checks that nothing is read
85	    // while the sidebar stays closed.
86	    if (!api.trailsView.visible) {
87	      assert.equal(repo.trails, undefined);
88	      assert.deepEqual(calls('trail '), []);
89	    }
90	    await vscode.commands.executeCommand('entire.trails.focus');
91	    await until(() => repo.trails && !repo.trails.loading, 'the first page of trails');
92	    assert.equal(api.manager.trailsState(), 'ready');
93	    // Only the first page has been asked for, with the project and repository
94	    // from the origin remote. No later page, and no single trail.
95	    assert.deepEqual([...new Set(calls('trail '))], [fixture.trailListOpen]);
96	  });
97	
98	  test('lists open trails a page at a time, most recent activity first', () => {
99	    const trails = trailRows();
100	    assert.equal(trails.length, 50);
101	    assert.deepEqual(
102	      trails.slice(0, 3).map((node) => node.trail.number),
103	      [120, 119, 118],
104	    );
105	    const more = loadMoreRow();
106	    assert.ok(more, 'there is more to load');
107	    assert.equal(more.noun, 'Trails');
108	    assert.equal(more.shown, 50);
109	    // The CLI says how many there are in all, so the row can too.
110	    assert.equal(more.total, 120);
111	    const item = api.trailsTree.getTreeItem(more);
112	    assert.equal(label(item), 'Load More Trails');
113	    assert.equal(item.description, '50 of 120 shown');
114	    assert.equal(api.trailsView.description, 'Open');
115	  });
116	
117	  test('describes a trail by its number, phase, and branch in this repository', () => {
118	    const [first, second] = trailRows();
119	    const item = api.trailsTree.getTreeItem(first);
120	    assert.equal(label(item), 'Trail 120');
121	    assert.match(item.description, /^#120 · building · main \(checked out\) · /);
122	    assert.equal(item.command.command, 'entire.openDetail');
123	    assert.match(item.contextValue, /^trail\b/);
124	    assert.match(item.contextValue, /\bweb\b/);
125	    assert.match(item.contextValue, /\bopenable\b/);
